# -*- coding: utf-8 -*-
import os
import time

from taf.playwright.core.utils import timeout_ms, to_bool


class PlaywrightPagePart(object):
    """Small product-neutral wrapper around Playwright Page."""

    def __init__(self, page):
        self.page = page

    @staticmethod
    def _timeout_ms(timeout):
        return timeout_ms(timeout)

    @property
    def context(self):
        return self.page.context

    def locator(self, selector):
        return self.page.locator(selector)

    def first(self, selector):
        return self.locator(selector).first

    def goto(self, url, timeout=60, wait_until="domcontentloaded"):
        self.page.goto(url, wait_until=wait_until, timeout=self._timeout_ms(timeout))

    def wait_for(self, selector, timeout=60, state="visible"):
        self.first(selector).wait_for(state=state, timeout=self._timeout_ms(timeout))
        return self.first(selector)

    def click(self, selector, timeout=60, force=False):
        self.first(selector).click(timeout=self._timeout_ms(timeout), force=force)

    def optional_click(self, selector, timeout=2, force=False):
        if self.is_visible(selector, timeout):
            self.click(selector, timeout, force=force)
            return True
        return False

    def fill(self, selector, value, timeout=60):
        self.first(selector).fill(str(value), timeout=self._timeout_ms(timeout))

    def text(self, selector, timeout=60):
        return self.first(selector).inner_text(timeout=self._timeout_ms(timeout)).strip()

    def value(self, selector, timeout=60):
        return self.first(selector).input_value(timeout=self._timeout_ms(timeout)).strip()

    def is_visible(self, selector, timeout=2):
        try:
            return self.first(selector).is_visible(timeout=self._timeout_ms(timeout))
        except Exception:
            return False

    def is_enabled(self, selector, timeout=2):
        try:
            return self.first(selector).is_enabled(timeout=self._timeout_ms(timeout))
        except Exception:
            return False

    def wait_for_text(self, selector, expected_text, timeout=60):
        locator = self.wait_for(selector, timeout=timeout)
        deadline = time.time() + float(timeout)
        while time.time() <= deadline:
            if expected_text in locator.inner_text(timeout=self._timeout_ms(1)):
                return True
            time.sleep(0.2)
        return False

    def set_checkbox(self, selector, expected=True, timeout=60):
        locator = self.first(selector)
        locator.wait_for(state="attached", timeout=self._timeout_ms(timeout))
        if bool(locator.is_checked()) != to_bool(expected):
            locator.click(timeout=self._timeout_ms(timeout))

    def select_option(self, selector, value=None, label=None, index=None, timeout=60):
        options = {}
        if value is not None:
            options["value"] = str(value)
        if label is not None:
            options["label"] = str(label)
        if index is not None:
            options["index"] = int(index)
        return self.first(selector).select_option(timeout=self._timeout_ms(timeout), **options)

    def upload_file(self, selector, file_path, timeout=60):
        self.first(selector).set_input_files(file_path, timeout=self._timeout_ms(timeout))

    def hover(self, selector, timeout=60):
        self.first(selector).hover(timeout=self._timeout_ms(timeout))

    def press(self, selector, key, timeout=60):
        self.first(selector).press(key, timeout=self._timeout_ms(timeout))

    def evaluate(self, script, arg=None):
        if arg is None:
            return self.page.evaluate(script)
        return self.page.evaluate(script, arg)

    def screenshot(self, path, full_page=True):
        target_dir = os.path.dirname(path)
        if target_dir and not os.path.exists(target_dir):
            os.makedirs(target_dir)
        self.page.screenshot(path=path, full_page=full_page)
        return path
